{
  "status": "INSUFFICIENT_EVIDENCE",
  "core_findings": [
    {
      "finding": "Serving parity is unavailable in all four categories, so history sensitivity cannot be interpreted. The observed failure is in diagnostic introspection; an actual serving-score defect has not been established.",
      "evidence": "Every category reports status=serving_parity_unavailable, serving_parity.available=false, passed=false, cases=0, checkpoint_serialization_verified=false, and history_sensitivity=null. All coverage flags are false. The shared error is TypeError: BERT4RecModel is a built-in class. Score errors, ranking agreements, and sensitivity uncertainty intervals are unavailable."
    },
    {
      "finding": "The supplied sampler checks pass, and Electronics has the weakest observed in-sample sampled-pair separation. These observations do not establish generalization or host validation HR@10.",
      "evidence": "For every category, sampler_contract.passed=true, reserved_tokens_valid=true, valid_batches=10, invalid_batches=0. In Movies_and_TV, Industrial_and_Scientific, Electronics, CDs_and_Vinyl order: pos_neg_margin_count=[2242,2250,2179,2709], pos_neg_margin_mean=[5.37788,3.63284,1.17929,4.80496], pos_neg_margin_p10=[1.01196,0.00930,-0.91089,0.55749], pos_neg_neg_beats_pos_rate=[0.05531,0.09956,0.24461,0.07235], and pos_neg_small_margin_rate=[0.07538,0.13067,0.35842,0.09635]. No uncertainty intervals are supplied for these statistics. Tensor checks do not verify prefix provenance or uniform negative sampling."
    },
    {
      "finding": "Sampled item embeddings have approximately zero mean off-diagonal cosine; representation capacity and recommendation quality remain unestablished.",
      "evidence": "embedding_collapse_score is 0.512379 for Movies_and_TV, 0.516821 for Industrial_and_Scientific, 0.513619 for Electronics, and 0.510139 for CDs_and_Vinyl; embedding_sample_count=2048 each. The mapping defines 0.5 as approximately zero mean cosine. Uncertainty intervals are unavailable."
    }
  ],
  "key_implications": [
    {
      "implication": "Repair the parity diagnostic and verify the exported checkpoint and scoring paths before drawing sensitivity conclusions; this is a verification prerequisite, not evidence that serving scores are wrong.",
      "evidence": "All four serving_parity.available flags are false, cases=0, checkpoint_serialization_verified=false, and short/full_length/truncated/batched_vs_individual coverage is absent. history_sensitivity and its intervals are unavailable throughout."
    },
    {
      "implication": "Electronics merits a training-objective or optimization hypothesis within the single BERT4Rec model, but any benefit requires independent validation using the fixed host protocol.",
      "evidence": "Electronics has pos_neg_margin_p10=-0.91089 and pos_neg_neg_beats_pos_rate=0.24461 across 2179 supervised positions, versus rates 0.05531–0.09956 elsewhere. These are in-sample measurements without uncertainty intervals; host validation HR@10 is not supplied. No gain or macro validation conclusion is supported, and repeated validation selection would be optimistic."
    },
    {
      "implication": "Withhold a four-category macro sensitivity conclusion and explanations involving unavailable attributes.",
      "evidence": "prefix_counts.candidate_examples=64 in each category, but history_sensitivity=null in all four, leaving zero categories with measured sensitivity outcomes or paired bootstrap intervals. Item-category breakdowns have available=false and empty lists. Ratings, review content, prices, stores, ownership, and simulator traits are unmeasured. Available prefix counts alone cannot establish sensitivity or recommendation quality."
    }
  ],
  "evidence": {
    "category_order": ["Movies_and_TV", "Industrial_and_Scientific", "Electronics", "CDs_and_Vinyl"],
    "scope": "Masked training-position margins and sampled embeddings; no host validation results supplied.",
    "uncertainty": "No sensitivity estimates or bootstrap intervals are available. Defined paired intervals would cover sampled-user uncertainty only, not training seeds or candidate sampling.",
    "external_label_invariance_tested": false
  }
}
